template<class T> 
class fifo_queue
{
private: 
  T *queue;
  short queue_max;
  short start;
  short end;
  short count;

public:
  T              pop();
  short          find(const T& index_to_find, short remove_flag);
};

template<class T>
short fifo_queue<T>::find(const T& index_to_find, short remove_flag)
{
  short curr = start;

  if (count <= 0)
    return 0;
  if (queue[curr] == index_to_find)
  {
    if (remove_flag)
    {
      pop();
    }
    return 1;
  }
  while (curr != end)
  {
    ++curr;
    if (curr >= queue_max)
      curr = 0;
    if (queue[curr] == index_to_find)
    {
      if (remove_flag)
      {
        queue[curr] = queue[end];
        --count;
        --end;
        if (end < 0)
          end = queue_max - 1;
      }
      return 1;
    }
  }
  return 0;
}

template short fifo_queue<unsigned int>::find(const unsigned int&, short);
